#include <bits/stdc++.h>
using namespace std;
// 统计 n 皇后解法数：逐行放皇后，列和两条对角线用布尔数组判冲突。
int n;
vector<int> col, d1, d2;
int cnt;
void dfs(int r) {
    if (r == n) { ++cnt; return; }
    for (int c = 0; c < n; ++c) {
        if (col[c] || d1[r + c] || d2[r - c + n]) continue;
        col[c] = d1[r + c] = d2[r - c + n] = 1;
        dfs(r + 1);
        col[c] = d1[r + c] = d2[r - c + n] = 0;
    }
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    if (!(cin >> n)) return 0;
    col.assign(n, 0); d1.assign(2 * n, 0); d2.assign(2 * n, 0);
    cnt = 0;
    dfs(0);
    cout << cnt << '\n';
    return 0;
}

