using namespace std;
// 生成 n 对括号的全部合法组合（'(' 优先即字典序）。
int n;
string cur;
vector<string> ans;
void dfs(int open_, int close_) {
    if ((int)cur.size() == 2 * n) { ans.push_back(cur); return; }
    if (open_ < n) { cur.push_back('('); dfs(open_ + 1, close_); cur.pop_back(); }
    if (close_ < open_) { cur.push_back(')'); dfs(open_, close_ + 1); cur.pop_back(); }
}
