    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    if (!(cin >> n)) return 0;
    dfs(0, 0);
    for (const string &s : ans) cout << s << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
// 含重复数字的全排列计数：排序 + 同层去重剪枝。
int n, cnt = 0;
vector<int> a, used;
void dfs(int depth) {
    if (depth == n) { ++cnt; return; }
    for (int i = 0; i < n; ++i) {
        if (used[i]) continue;
        if (i > 0 && a[i] == a[i - 1] && !used[i - 1]) continue;
        used[i] = 1;
        dfs(depth + 1);
        used[i] = 0;
    }
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    if (!(cin >> n)) return 0;
    a.resize(n); used.assign(n, 0);
    for (int i = 0; i < n; ++i) cin >> a[i];
    sort(a.begin(), a.end());
    dfs(0);
    cout << cnt << '\n';
    return 0;
}

