#include <bits/stdc++.h>
using namespace std;
// 网格路径计数（只向右/向下，1 为障碍）：递归 + 记忆化。
int n, m;
vector<vector<int>> g, memo;
int dfs(int r, int c) {
    if (r >= n || c >= m || g[r][c] == 1) return 0;
    if (r == n - 1 && c == m - 1) return 1;
    int &res = memo[r][c];
    if (res != -1) return res;
    return res = dfs(r + 1, c) + dfs(r, c + 1);
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    if (!(cin >> n >> m)) return 0;
    g.assign(n, vector<int>(m));
    memo.assign(n, vector<int>(m, -1));
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j) cin >> g[i][j];
    cout << dfs(0, 0) << '\n';
    return 0;
}

