from collections import deque


def nearest_source(grid):
    """grid 中 0 为源，返回每个格子到最近源的距离。"""
    n, m = len(grid), len(grid[0])
    dist = [[-1] * m for _ in range(n)]
    q = deque()
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 0:
                dist[i][j] = 0
                q.append((i, j))
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))
    while q:
        r, c = q.popleft()
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m and dist[nr][nc] == -1:
                dist[nr][nc] = dist[r][c] + 1
                q.append((nr, nc))
    return dist


if __name__ == '__main__':
    import sys
    data = list(map(int, sys.stdin.read().split()))
    n, m = data[0], data[1]
    vals = data[2:]
    grid = [vals[i * m:(i + 1) * m] for i in range(n)]
    for row in nearest_source(grid):
        print(' '.join(map(str, row)))

