import sys
sys.setrecursionlimit(100000)


def has_cycle(n, edges):
    """有向图三色标记判环：0 未访问，1 在栈中，2 已完成。"""
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
    color = [0] * (n + 1)

    def dfs(u):
        color[u] = 1
        for v in adj[u]:
            if color[v] == 1:
                return True
            if color[v] == 0 and dfs(v):
                return True
        color[u] = 2
        return False

    return any(color[i] == 0 and dfs(i) for i in range(1, n + 1))


if __name__ == '__main__':
    data = list(map(int, sys.stdin.read().split()))
    n, m = data[0], data[1]
    edges = [(data[2 + 2 * i], data[3 + 2 * i]) for i in range(m)]
    print("YES" if has_cycle(n, edges) else "NO")

