#include <bits/stdc++.h>
using namespace std;
// 有向图判环：三色标记 DFS。0 未访问，1 在栈中，2 已完成。
int n;
vector<vector<int>> adj;
vector<int> color;
bool dfs(int u) {
    color[u] = 1;
    for (int v : adj[u]) {
        if (color[v] == 1) return true;
        if (color[v] == 0 && dfs(v)) return true;
    }
    color[u] = 2;
    return false;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int m;
    if (!(cin >> n >> m)) return 0;
    adj.assign(n + 1, {});
    for (int i = 0; i < m; ++i) { int u, v; cin >> u >> v; adj[u].push_back(v); }
    color.assign(n + 1, 0);
    bool cycle = false;
    for (int i = 1; i <= n && !cycle; ++i)
        if (color[i] == 0) cycle = dfs(i);
    cout << (cycle ? "YES" : "NO") << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
// 无向连通图 Prim 最小生成树（堆优化），返回总权值。
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    if (!(cin >> n >> m)) return 0;
    vector<vector<pair<int,int>>> adj(n + 1);
    for (int i = 0; i < m; ++i) {
        int u, v, w; cin >> u >> v >> w;
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    }
    vector<int> in_tree(n + 1, 0);
    using P = pair<int,int>;
    priority_queue<P, vector<P>, greater<P>> pq;
    pq.push({0, 1});  // 起点边权记 0
    long long total = 0;
    int cnt = 0;
    while (!pq.empty() && cnt < n) {
        auto [w, u] = pq.top(); pq.pop();
        if (in_tree[u]) continue;
        in_tree[u] = 1;
        total += w;
        ++cnt;
        for (auto [v, w2] : adj[u])
            if (!in_tree[v]) pq.push({w2, v});
    }
    cout << total << '\n';
    return 0;
}
